#!/usr/bin/env python3
"""Genera plan/specs/dia_NNN.md: el encargo de cada día del ciclo 1 (qué cubrir, pasajes, versículos clave, lectura y pistas de búsqueda).
Los redactores leen su ficha; no se repiten prompts. Uso: python3 specs_ciclo1.py"""
import os
AQUI = os.path.dirname(os.path.abspath(__file__)); os.makedirs(f'{AQUI}/specs', exist_ok=True)

# dia: (contenido, versículos clave, lectura, pistas de búsqueda)
D = {
7: ('Qué significa «canon» (kanón: caña, regla) y por qué un pueblo que cree que Dios habló necesita saber qué libros son esa Palabra; la idea de canon como regla de fe y de vida; la diferencia entre canon (lista autoritativa) y colecciones útiles; criterios generales; la Iglesia reconoce el canon, no lo crea (postura protestante) frente a la postura católica romana de la autoridad de la Iglesia para determinarlo (presentada tal como la describen las fuentes); canon abierto o cerrado; Dios inspira y el pueblo reconoce. Textos: Deuteronomio 31:24-26; Lucas 24:44; 1 Timoteo 5:18; 2 Pedro 3:15-16.', 'Lucas 24:44; 2 Pedro 3:16', 'Lucas 24:25-27, 44-49; 2 Pedro 3:14-16', 'canon|can[oó]nic; web_* sobre canon; grudem, macarthur_ts, ryrie, chafer'),
8: ('Canon del Antiguo Testamento: las tres partes (Ley, Profetas, Escritos) y cómo Jesús se refiere al AT (Lucas 24:44; Mateo 23:35 «de Abel a Zacarías»); orden y número de libros en el canon judío y protestante; los libros deuterocanónicos o apócrifos y las posturas: protestante (excluidos) y católica romana (incluidos, Trento 1546), cada una con su documento primario si está en las fuentes web; criterios con que se reconoció; el supuesto «concilio de Jamnia» y lo que se discute; Josefo; la Septuaginta y las listas. Romanos 3:1-2.', 'Lucas 24:44; Romanos 3:2', 'Lucas 24:44-48; Romanos 3:1-4', 'canon|Jamn|apócrifo|deuterocan; web_* canon AT; macarthur_ts, ryrie, chafer, lacueva'),
9: ('Canon del Nuevo Testamento: cómo se formó (no por un concilio que lo inventó); criterios (origen apostólico, ortodoxia, uso universal de la iglesia, testimonio interno); testimonios tempranos: 2 Pedro 3:15-16 (Pablo entre «las otras Escrituras»), 1 Timoteo 5:18 (cita a Lucas), Fragmento Muratori, Atanasio (Carta pascual 367), Concilios de Hipona y Cartago; los libros discutidos (Hebreos, Santiago, 2 Pedro, 2-3 Juan, Judas, Apocalipsis) y cómo se resolvió; posturas.', '2 Pedro 3:16; 1 Timoteo 5:18', '2 Pedro 3:14-18; 1 Timoteo 5:17-18', 'canon|Muratori|Atanasio|Cartago|antilegomena; web_* canon NT; macarthur_ts, ryrie, grudem, geisler'),
10: ('Los libros que quedaron fuera: los apócrifos del AT (Tobías, Judit, Sabiduría, Eclesiástico, Macabeos) y por qué los protestantes no los reciben; seudoepigráficos (Enoc: Judas 14-15 lo cita); evangelios apócrifos y gnósticos (Tomás, Judas, Felipe): cuándo se escribieron, qué enseñan y por qué no entraron; que una cita de un autor no canónico (Hechos 17:28, Tito 1:12, Judas 14) no lo vuelve Escritura; cómo conversar con quien dice que «se ocultaron libros».', 'Judas 3; 1 Juan 4:1', 'Judas 1:3-4, 14-15; Hechos 17:22-28', 'apócrif|gn[oó]stic|Tom[aá]s|Enoc|c[oó]digo; strobel, geisler, macarthur_ts, web_* canon NT'),
11: ('De los autógrafos a las copias: cómo se escribía (rollos, papiro, pergamino, códice), qué eran los escribas y los copistas; Jeremías 36 (dictado a Baruc, rollo quemado y reescrito); la copia de la ley (Deuteronomio 17:18); el cuidado de los escribas judíos y la tarea de los masoretas; errores de copia y por qué se conserva el mensaje; autógrafos perdidos y la doctrina de la inspiración aplicada a los originales y las copias (Mateo 5:18).', 'Jeremías 36:32; Mateo 5:18', 'Jeremías 36:1-4, 20-32; Deuteronomio 17:18-20', 'autógrafo|copista|escriba|papiro|masoret; geisler, strobel, grudem, ryrie; web_* transmisión del texto'),
12: ('El texto del Antiguo Testamento: texto masorético (Códice de Leningrado, de Alepo) y la tarea de los masoretas; la Septuaginta (origen, uso en el NT, diferencias); los rollos del Mar Muerto (descubrimiento 1947, Qumrán, el rollo de Isaías) y lo que mostraron sobre la fidelidad de la transmisión; cómo se usan hoy; fuentes web del Museo de Israel.', 'Isaías 40:8; 1 Pedro 1:24-25', 'Isaías 40:1-8; 1 Pedro 1:22-25', 'Septuaginta|LXX|masor|Mar Muerto|Qumr; web_* rollos y masoretas; geisler, strobel, macarthur_ts'),
13: ('Los manuscritos del Nuevo Testamento: papiros (P52, P46, P66, P75), códices unciales (Sinaítico, Vaticano, Alejandrino, Beza), minúsculos, leccionarios; cantidad y antigüedad de los manuscritos griegos y de las versiones antiguas (latinas, siríacas, coptas) y de las citas de los Padres, y cómo lo comparan los autores con obras clásicas; cifras SOLO si están en las fuentes citadas del día (y con su fecha); qué se infiere y qué no.', 'Lucas 1:3-4; 2 Timoteo 4:13', 'Lucas 1:1-4; 2 Timoteo 4:9-13', 'manuscrit|papiro|Sinait|Vaticano|P52; strobel, geisler, mcdowell; web_* manuscritos (CSNTM, Codex Sinaiticus)'),
14: ('La crítica textual: de dónde vienen las variantes, tipos (de ortografía, de orden, de omisión y adición), por qué la mayoría no afecta nada; reglas básicas; ejemplos disputados (Marcos 16:9-20, Juan 7:53–8:11, 1 Juan 5:7); las posturas: texto crítico, texto mayoritario, Textus Receptus (cada una con sus defensores y razones, tal como los presenten las fuentes); cómo se relaciona con la inerrancia (día 4) y con la fidelidad de la Biblia; Mateo 24:35.', 'Mateo 24:35; Salmo 12:6', 'Marcos 16:1-8; Juan 7:53–8:11 (leer y ver las notas de tu Biblia)', 'variante|cr[ií]tica textual|Textus Receptus|mayoritario; macarthur_ts, geisler, strobel; web_* crítica textual'),
15: ('De las lenguas originales a la tuya: historia de las traducciones. Septuaginta, Vulgata de Jerónimo, versiones antiguas, Wycliffe, Lutero, Tyndale, la Biblia King James; la Biblia en español: Casiodoro de Reina (1569), Cipriano de Valera (1602), revisiones de 1862, 1909 y 1960, versiones actuales (RVA, NVI, LBLA, DHH, NTV, RV2015); por qué se traduce y por qué se sigue traduciendo; Nehemías 8:8; Hechos 2:6-11.', 'Nehemías 8:8; Hechos 2:11', 'Nehemías 8:1-8; Hechos 2:1-12', 'traducci[oó]n|Reina|Valera|Lutero|Wycliffe|Tyndale|Vulgata; web_* historia de las traducciones y Biblia en español'),
16: ('Cómo elegir y comparar traducciones: filosofías (formal o literal, dinámica o funcional, paráfrasis), texto base que usa cada una, a quién apuntan; el mismo pasaje en varias versiones (por ejemplo Efesios 2:8-9 y 1 Corintios 6:9-11) y qué se gana comparando; criterios prácticos para estudiar, predicar y leer en voz alta; los límites de cada versión; la importancia de no depender de una sola; qué decir de las paráfrasis; la RVR1960 con la que se trabaja en este estudio (por qué y qué conviene saber de ella).', 'Nehemías 8:8; Salmo 119:105', 'Efesios 2:8-10 (en dos o tres versiones); Nehemías 8:5-8', 'traducci[oó]n|versi[oó]n|literal|din[aá]mic|paráfrasis; web_* traducciones; grudem, lacueva'),
17: ('Por qué interpretar bien importa: hermenéutica (el arte y la ciencia de interpretar) y exégesis (sacar el sentido del texto) frente a eiségesis (meterle el propio); las distancias entre el lector y el texto (tiempo, cultura, idioma, género); ejemplos bíblicos de buena y mala interpretación (Satanás cita el Salmo 91 en Mateo 4; Jesús en Lucas 24; el eunuco en Hechos 8:30-35); 2 Pedro 1:20 y 3:16; Nehemías 8:8; 2 Timoteo 2:15; las consecuencias de interpretar mal (sectas, abusos).', '2 Timoteo 2:15; Hechos 8:30-31', 'Hechos 8:26-39; Mateo 4:1-11', 'herme[nn]éutic|ex[eé]gesis|eis[eé]gesis; grudem, macarthur_ts, lacueva; libros de hermenéutica recién registrados (buscá en libros.json)'),
18: ('La primera regla: el contexto. Contexto inmediato, del libro, de la sección de la Biblia y de toda la Biblia (la Escritura interpreta a la Escritura); ejemplos de versículos usados fuera de contexto (Jeremías 29:11, Filipenses 4:13, Mateo 18:20, Jueces 6, Romanos 8:28) y cómo cambia su sentido leídos en contexto; criterios para saber a quién iba dirigido y qué se promete; la frase «un texto fuera de contexto es un pretexto» (solo si una fuente la trae).', 'Jeremías 29:11; Filipenses 4:13', 'Jeremías 29:1-14; Filipenses 4:10-20', 'contexto|fuera de contexto|Jerem[ií]as 29|Filipenses 4:13; grudem, macarthur_ts, lacueva, geisler (dificultades)'),
19: ('El contexto literario: de la palabra a la oración, al párrafo, a la sección y al libro; conectores («por tanto», «porque», «pero») y estructura del argumento (Romanos 12:1, Efesios 2:1-10); recursos hebreos y griegos: paralelismo, quiasmo, inclusión, repetición; cómo se reconoce la idea central de un párrafo; ejemplo trabajado con un pasaje corto.', 'Romanos 12:1; Efesios 2:8-10', 'Efesios 2:1-10; Romanos 11:33–12:2', 'quiasmo|paralelismo|inclusi[oó]n|conector|contexto literario; web_* hermenéutica; comentarios de Efesios/Romanos'),
20: ('El contexto histórico y cultural: preguntas (quién escribe, a quién, cuándo, en qué situación, qué costumbres); ejemplos que cambian el sentido (la samaritana en Juan 4, el buen samaritano en Lucas 10, Laodicea «ni frío ni caliente» en Apocalipsis 3:15-16, las vestiduras, el pozo, hospitalidad); fuentes para averiguar (diccionarios bíblicos, comentarios, arqueología); el riesgo de leer con ojos modernos y el de sobreinterpretar la cultura; lo permanente y lo cultural en un mandato.', 'Apocalipsis 3:15-16; Juan 4:9', 'Juan 4:1-26; Apocalipsis 3:14-22', 'cultura|costumbre|contexto histórico|trasfondo|Laodicea|samaritan; diccionario bíblico (registro), comentarios de Juan y Apocalipsis, web_* arqueología'),
21: ('Cómo se ha interpretado la Biblia en la historia: la lectura judía (peshat, midrash), Jesús y los apóstoles, la escuela alegórica de Alejandría (Orígenes) y la de Antioquía, los cuatro sentidos medievales, los reformadores (el sentido llano, la Escritura interpreta a la Escritura), la crítica histórica moderna y la lectura actual; el método gramático-histórico y por qué lo defienden la mayoría de las fuentes; el lugar de la analogía de la fe; posturas diferentes donde las haya.', '2 Timoteo 3:16; Salmo 119:18', 'Gálatas 4:21-31 (¿alegoría?); Lucas 24:25-27', 'alegór|gramático|literal|Orígenes|Reforma|método; macarthur_ts, grudem, lacueva, sproul; web_* historia de la interpretación'),
22: ('Estudio bíblico inductivo (1): observar. Qué es el método inductivo (partir del texto, no de lo que ya creemos); las preguntas básicas (quién, qué, cuándo, dónde, por qué, cómo); palabras repetidas, contrastes, listas, causas y efectos, verbos, conectores, tono; herramientas prácticas (marcar, tabla, esquema); se trabaja un ejemplo completo con el Salmo 1 (el mismo pasaje se usa en los días 22, 23 y 24).', 'Salmo 1:1-2; Hechos 17:11', 'Salmo 1', 'inductivo|observaci[oó]n|observar; web_* estudio bíblico inductivo; libros de método'),
23: ('Estudio bíblico inductivo (2): interpretar. De la observación al significado: preguntar «¿qué quiso decir el autor a sus primeros lectores?»; contexto, palabras clave y su sentido, géneros, pasajes paralelos y referencias cruzadas, comentarios (cuándo y cómo usarlos); se continúa el ejemplo del Salmo 1 (qué es «el consejo de malos», «meditar», «el camino de los justos») con ayuda de las fuentes.', 'Salmo 1:2; 2 Timoteo 2:15', 'Salmo 1; Josué 1:7-9', 'interpretar|interpretaci[oó]n|Salmo 1|meditar; comentarios del Salmo 1 (Spurgeon, Beacon, Walvoord), web_* método inductivo'),
24: ('Estudio bíblico inductivo (3): aplicar. Del significado a la vida: la distancia entre el texto y hoy; principio permanente frente a mandato circunstancial; preguntas de aplicación (¿qué enseña de Dios? ¿del ser humano? ¿qué debo creer, dejar, hacer?); aplicación personal, familiar y comunitaria; el peligro de aplicar sin interpretar y de interpretar sin aplicar (Santiago 1:22-25); se cierra el ejemplo del Salmo 1.', 'Santiago 1:22; Salmo 1:3', 'Santiago 1:19-27; Salmo 1', 'aplicaci[oó]n|aplicar|Santiago 1:22; grudem, macarthur_ts, lacueva; web_* aplicación'),
25: ('Cómo leer los relatos del Antiguo Testamento: tres niveles (el plan de Dios para toda la creación, la historia de Israel y las historias de individuos); la trama, los personajes y el narrador; lo descriptivo frente a lo prescriptivo (que algo ocurra no significa que sea modelo); el peligro de moralizar y alegorizar (David y Goliat: ¿modelo de valentía o anuncio del rey de Dios?); cómo se junta una historia con otra; ejemplos de 1 Samuel 17 y Génesis 22.', 'Romanos 15:4; 1 Corintios 10:11', '1 Samuel 17:1-11, 32-51; 1 Corintios 10:1-13', 'narrativ|relato|descriptiv|prescriptiv|1 Samuel 17; grudem, lacueva, macarthur_ts; web_* género narrativo'),
26: ('Cómo leer la Ley: qué es la Torá, el pacto mosaico y sus partes (leyes morales, civiles, ceremoniales: una división tradicional y las críticas que recibe); qué hacer con Levítico y Deuteronomio hoy; Jesús y la ley (Mateo 5:17-20), Romanos 10:4, Gálatas 3:24-25, Hechos 15; la ley como sombra (Hebreos 10:1); las distintas posturas cristianas (continuidad, discontinuidad, la ley de Cristo) con sus defensores según las fuentes.', 'Mateo 5:17; Gálatas 3:24', 'Éxodo 20:1-17; Mateo 5:17-20', 'ley|Tor[aá]|moral|ceremonial|civil|bajo la ley; macarthur_ts, grudem, berkhof, ryrie, chafer'),
27: ('Cómo leer la poesía hebrea y los Salmos: paralelismo (sinónimo, antitético, sintético), imágenes, lenguaje emocional, acrósticos; los géneros de Salmos (lamento, alabanza, acción de gracias, realeza, sabiduría, imprecatorios); el Salmo como oración y como Palabra; cómo leer los salmos imprecatorios; Cristo en los Salmos (Lucas 24:44); ejemplos: Salmos 23, 51 y 137.', 'Salmo 23:1; Salmo 51:10', 'Salmo 23; Salmo 51', 'poes[ií]a|paralelismo|Salmos|imprecatori; Spurgeon (El tesoro de David, si está), Piper Moldeados por Dios, Beacon; web_* poesía hebrea'),
28: ('Cómo leer la literatura sapiencial: Proverbios (principios generales, no promesas automáticas: Proverbios 22:6), Job (el sufrimiento y la sabiduría; los amigos hablan mal de Dios, Job 42:7), Eclesiastés (vida «debajo del sol»), Cantares; la sabiduría como temor de Jehová (Proverbios 1:7); los géneros del refrán, el diálogo y la reflexión; cómo evitar convertir un proverbio en promesa.', 'Proverbios 1:7; Job 42:7', 'Proverbios 1:1-7; Job 42:1-9', 'sabidur[ií]a|Proverbios|Eclesiast|Job|refrán; Beacon, Walvoord, Spurgeon, MacArthur; web_* literatura sapiencial'),
29: ('Cómo leer la profecía: el profeta como portavoz de Dios (decir y predecir); condicionales e incondicionales (Jonás 3, Jeremías 18:7-10); cumplimientos próximos y lejanos, cumplimientos en etapas; lenguaje poético y simbólico; criterios de un profeta verdadero (Deuteronomio 18:20-22); cómo cita el NT a los profetas (Joel 2 en Hechos 2, Isaías 7:14 en Mateo 1:23); posturas sobre cumplimiento literal y simbólico, solo las que traigan las fuentes.', 'Deuteronomio 18:22; Jeremías 18:7-8', 'Jonás 3; Hechos 2:14-21', 'profec[ií]a|profeta|condicional|cumplimiento; grudem, macarthur_ts, chafer, ryrie; carballosa (Apocalipsis), web_* profecía'),
30: ('Cómo leer la literatura apocalíptica: Daniel y Apocalipsis; símbolos, números e imágenes; el contexto de persecución; enfoques de interpretación (preterista, historicista, futurista, idealista) y quién los defiende, según las fuentes; lo que el propio Apocalipsis dice de sí (Apocalipsis 1:1-3; 22:7); cómo leer un símbolo (¿qué significa en el AT?).', 'Apocalipsis 1:3; Daniel 7:13-14', 'Apocalipsis 1:1-8; Daniel 7:1-14', 'apocal[ií]ptic|Apocalipsis|símbolo|preterista|futurista|idealista; Carballosa, Ladd, Hanegraaff, Larkin, MacArthur'),
31: ('Cómo leer los Evangelios y las parábolas: cuatro retratos del único Jesús, su género y propósito; leer un pasaje en su contexto (la cruz y el reino); las parábolas (género, un punto central, contexto, el peligro de alegorizar cada detalle, Marcos 4:10-12); ejemplos: el sembrador y el hijo pródigo (Lucas 15); armonía de los Evangelios; qué se pierde si se leen como cuentos de moral.', 'Marcos 4:9; Juan 20:31', 'Lucas 15:1-32; Marcos 4:1-20', 'parábola|Evangelio|sinóptic; Pink (Las parábolas de Mateo), MacArthur (Mateo, Lucas), Barclay, Guzik; web_* parábolas'),
32: ('Cómo leer Hechos: narrativa histórica de Lucas con propósito teológico; lo descriptivo frente a lo normativo (comunidad de bienes en Hechos 2:44-45, la sucesión de lenguas y bautismos, el sorteo de Matías); cómo saber qué es modelo (repetición, enseñanza explícita en las cartas); transición entre épocas; posturas de los autores donde difieran (por ejemplo sobre la repetición de Pentecostés), con sus razones.', 'Hechos 1:8; Hechos 2:42', 'Hechos 2:1-4, 41-47; Hechos 8:14-17', 'Hechos|descriptiv|normativ|transici[oó]n|Pentecostés; MacArthur, Grudem, Ryrie, comentarios de Hechos'),
33: ('Cómo leer las cartas: género epistolar, situación concreta; leer «una mitad de la conversación»; estructura (saludo, enseñanza, exhortación, despedida); mandatos de entonces y de hoy (el saludo santo, cubrirse la cabeza en 1 Corintios 11, comer carne ofrecida a ídolos); cómo distinguir lo cultural de lo permanente; ejemplo con Filemón o 1 Corintios 8.', '2 Timoteo 3:16; Filemón 1:15-16', 'Filemón; 1 Corintios 8:1-13', 'epístola|carta|cultural|permanente|Filemón|1 Corintios 8; comentarios de las cartas; web_* epístolas'),
34: ('Figuras, símbolos y tipos: metáfora, símil, hipérbole, ironía, metonimia, personificación (ejemplos); cuándo algo es literal y cuándo figurado; el símbolo en la Biblia y el de los números y colores (con cuidado); tipología (Romanos 5:14, 1 Corintios 10:6, Hebreos 8:5, Juan 3:14, Mateo 12:40) y cómo se distingue de la alegoría; criterios para reconocer un tipo legítimo (que el NT lo indique, correspondencia histórica y teológica); posturas.', 'Romanos 5:14; Hebreos 8:5', 'Juan 3:1-15; Hebreos 8:1-6', 'tipo|tipolog[ií]a|símbolo|figura|metáfora|alegor; grudem, macarthur_ts, lacueva, Hebreos (Kistemaker)'),
35: ('El Antiguo Testamento en el Nuevo: citas directas, alusiones, ecos; cómo citan los apóstoles (a veces de la Septuaginta); cumplimientos que los autores señalan (Mateo 2:15 y Oseas 11:1, Hechos 15:15-18 y Amós 9:11-12, Gálatas 4:21-31); las distintas explicaciones sobre cómo usan los apóstoles el AT y lo que las fuentes dicen sobre su legitimidad; qué hacemos nosotros con eso.', 'Lucas 24:27; Mateo 2:15', 'Mateo 2:13-18; Oseas 11:1-4; Hechos 15:12-21', 'Antiguo Testamento en el Nuevo|cita|Mateo 2:15|Oseas 11:1|Septuaginta; macarthur_ts, grudem, Beacon, Walvoord; web_* uso del AT en el NT'),
36: ('Pasajes difíciles, errores comunes y el papel del Espíritu y de la comunidad: lista de errores (sacar de contexto, espiritualizar todo, ignorar el género, leer solo con lo propio, palabras-fetiche, mirar solo el versículo favorito); pasos ante un pasaje difícil (¿qué dice?, ¿qué quiso decir?, ¿qué otros textos hablan?, ¿qué dicen los comentarios?); el papel del Espíritu en la interpretación (1 Corintios 2:12-14; Efesios 1:17-18); interpretar en comunidad y con maestros (Efesios 4:11-14; Hechos 17:11); humildad y desacuerdos legítimos; cierra la serie y enlaza con la serie de idiomas.', '1 Corintios 2:12; Hechos 17:11', 'Hechos 17:10-12; 1 Corintios 2:10-16', 'Espíritu|iluminaci[oó]n|errores|difícil|pasajes dif; grudem, macarthur_ts, sproul, geisler (dificultades); web_*'),
37: ('El hebreo bíblico: alfabeto de 22 consonantes (alef-bet), se escribe de derecha a izquierda; las vocales las agregaron los masoretas; raíces de tres consonantes y cómo se forman palabras; transliteración y lectura básica; la forma del verbo y el sentido; cómo ayudarse sin ser experto; ejemplos de Génesis 1:1 (bereshit bará Elohim) y Salmo 23:1; qué se pierde y qué se gana al mirar el original.', 'Génesis 1:1; Salmo 23:1', 'Génesis 1:1-5; Salmo 23', 'hebreo|hebrea|alef|ra[ií]z|consonante; web_* hebreo bíblico; macarthur_ts, grudem, lacueva'),
38: ('El arameo bíblico y las lenguas alrededor de la Biblia: pasajes en arameo (Daniel 2:4b–7:28, Esdras 4:8–6:18 y 7:12-26, Jeremías 10:11, Génesis 31:47); por qué el arameo fue lengua común en el exilio; el arameo en la boca de Jesús (talita cumi, efata, abba, maranata, Eloi Eloi lama sabactani); otras lenguas (acadio, egipcio, ugarítico, latín); qué importa para leer.', 'Daniel 2:4; Marcos 5:41', 'Daniel 2:1-13; Marcos 5:35-43', 'arameo|aram|talita|abba|maranata; web_* arameo; Beacon, Walvoord (Daniel), MacArthur'),
39: ('El griego koiné: la lengua común del mundo helenístico después de Alejandro; por qué el NT se escribió en griego; el descubrimiento de papiros cotidianos que confirmó que es el griego de la calle; algunas características (artículo, aspecto verbal, casos) con ejemplos sencillos; las expresiones arameas en el NT; Hechos 21:37 y Juan 19:20; qué es eso de «el griego dice» y cómo no ser engañado.', 'Juan 19:20; Hechos 21:37', 'Juan 19:16-22; Hechos 21:37-40', 'griego|koin[eé]|helen|papiros; web_* griego koiné; macarthur_ts, grudem, lacueva; Hechos (comentarios)'),
40: ('Cómo usar un léxico y los números de Strong sin ser experto: qué es un léxico (Strong, Vine, BDAG, HALOT, diccionarios con números), cómo se busca una palabra desde una Biblia en español (interlineales y enlaces), qué dice y qué no dice una entrada; límites del Strong (es un índice, no un léxico completo); un ejemplo guiado (por ejemplo el verbo «conocer», que se vio en el día 1); herramientas gratuitas confiables (con su URL, de las fuentes web registradas).', '2 Timoteo 2:15; Salmo 119:18', 'Juan 21:15-19 (leer en dos versiones)', 'l[eé]xico|Strong|diccionario|interlineal; web_* léxicos/Strong; diccionario bíblico Mundo Hispano (ref4)'),
41: ('Falacias léxicas: errores comunes al estudiar palabras (D. A. Carson, Exegetical Fallacies, o resúmenes serios): la falacia etimológica (ekklesia como «los llamados fuera»), «semántica totalizadora ilegítima» (cargar todos los sentidos a un uso), anacronismo (dynamis y la dinamita), el significado «original», diferencia entre palabra y concepto; el caso de agapao/fileo en Juan 21 y la lectura que los distingue demasiado; cómo hacer bien un estudio de palabras.', '2 Timoteo 2:15; Juan 21:17', 'Juan 21:15-19', 'falacia|etimolog|ekklesia|dynamis|agap|fil[eé]o; web_* falacias léxicas; macarthur_ts, grudem'),
42: ('Palabras clave del Antiguo Testamento: hesed (lealtad de pacto), shalom, kabod (gloria), qadosh (santo), berit (pacto), tsedaqah (justicia), emunah y aman (fidelidad, creer), torah, ruaj (espíritu, viento), nefesh (alma, ser); cada una con un par de pasajes y su relación con otros días del estudio; solo las que las fuentes comentan; con la grafía hebrea verificada.', 'Éxodo 34:6; Isaías 6:3', 'Éxodo 34:5-9; Isaías 6:1-8', 'hesed|jésed|shalom|kabod|qadosh|berit|tsedaq|emun|ruaj|nefesh; macarthur_ts, grudem, pink, tozer; diccionario bíblico Mundo Hispano; web_* palabras del AT'),
43: ('Palabras clave del Nuevo Testamento: agape, pistis, charis, logos, ekklesia, euangelion, metanoia, dikaiosyne, koinonia, parakletos, basileia; cada una con pasajes y relación con otros días del estudio; solo las que las fuentes comentan; la grafía griega verificada.', 'Juan 1:14; Efesios 2:8', 'Juan 1:1-18; Efesios 2:1-10', 'agape|pistis|charis|logos|ekklesia|euangelion|metanoia|dikaiosyn|koinonia|par[aá]clet|basileia; macarthur_ts, grudem, berkhof, ryrie; diccionario Mundo Hispano; web_*'),
44: ('La Septuaginta y el vocabulario del Nuevo Testamento: Kyrios traduce YHWH (por eso Filipenses 2:11 y Romanos 10:13 dicen lo que dicen), Christos y Mesías, ekklesia y qahal, la justificación, doxa y kabod; citas del NT de la LXX (Hebreos 10:5 y Salmo 40:6, Hechos 15:17); qué cambia al conocer este puente entre los dos testamentos; límites y cautelas.', 'Filipenses 2:11; Romanos 10:13', 'Romanos 10:5-13; Filipenses 2:5-11', 'Septuaginta|LXX|Kyrios|Se[nñ]or; macarthur_ts, grudem, lacueva; web_* Septuaginta'),
45: ('Una sola historia: la Biblia en seis actos (creación, caída, Israel, Cristo, la Iglesia, la consumación); por qué los 66 libros son una historia y no una antología; los hilos que la atraviesan (reino, pacto, presencia, promesa); cómo leyó Jesús el AT (Lucas 24:27, 44); cómo resumen esa historia los apóstoles (Hechos 13:16-41; Hebreos 1:1-2); presentación de qué se verá en cada acto en los días siguientes.', 'Lucas 24:27; Hebreos 1:1-2', 'Lucas 24:13-35; Hechos 13:16-41', 'historia de la redención|teolog[ií]a bíblica|panorama|hilo|pacto|reino; ref4 «La Biblia en cápsulas», «Libro por libro»; web_* panorama'),
46: ('Acto 1, la creación: Génesis 1–2 y su eco en los Salmos 8, 19 y 104, en Juan 1 y Colosenses 1:15-17; un mundo bueno, la imagen de Dios, el mandato de cultivar y cuidar, el sábado y el descanso, el Edén como lugar de presencia; las distintas lecturas sobre Génesis 1 (por ejemplo, de seis días, de época, marco literario) solo las que traigan las fuentes, sin zanjar; por qué este acto es el telón de fondo de todo el resto.', 'Génesis 1:27; Colosenses 1:16', 'Génesis 1:26–2:3; Colosenses 1:15-20', 'creaci[oó]n|imagen de Dios|Edén|Génesis 1; grudem, macarthur_ts, berkhof, geisler; los comentarios de Génesis del estudio de Génesis (kline, edersheim) si están registrados'),
47: ('Acto 2, la caída: Génesis 3–11 (la serpiente, el pecado de Adán y Eva, el juicio, Caín, el diluvio, Babel); sus efectos (muerte, alienación, trabajo con dolor, el mundo roto); Romanos 5:12-21 y 1 Corintios 15:21-22; la promesa de Génesis 3:15 y la gracia en medio del juicio; el problema que el resto de la Biblia viene a resolver.', 'Génesis 3:15; Romanos 5:12', 'Génesis 3:1-24; Romanos 5:12-21', 'ca[ií]da|Adán|pecado original|Génesis 3:15|protoevangelio; grudem, berkhof, macarthur_ts, chafer, sproul'),
48: ('Acto 3, la promesa y la historia de Israel: Abraham y la promesa (Génesis 12), el éxodo y la ley, la tierra, los jueces, el reino de David y Salomón, la monarquía dividida, los profetas, el exilio y el retorno, los cuatrocientos años de silencio; cómo cada etapa mantiene viva la promesa y deja un anhelo (un rey, un sacerdote, un profeta, una tierra, un nuevo corazón); Gálatas 3:8 y 3:16.', 'Génesis 12:3; Gálatas 3:8', 'Génesis 12:1-7; Gálatas 3:6-18', 'Abraham|pacto|éxodo|monarqu[ií]a|exilio|profetas; kline, edersheim, macarthur, comentarios de históricos; web_* historia de Israel'),
49: ('Acto 4, Jesucristo: el cumplimiento de la historia (Gálatas 4:4; Marcos 1:15); el Rey, el Siervo, el Hijo del Hombre; su vida, muerte y resurrección como el centro (1 Corintios 15:3-4); cómo los Evangelios cuentan que en él se cumplen la ley, los profetas y los salmos; qué cambia con su venida; preludio de los ciclos 3 y 6.', 'Gálatas 4:4; 1 Corintios 15:3-4', 'Lucas 24:36-49; Gálatas 4:1-7', 'cumplimiento|Cristo|encarnaci[oó]n|cruz|resurrecci[oó]n; sproul (Quién es Jesús), stott, macarthur_ts, grudem'),
50: ('Acto 5, la Iglesia y la misión: Pentecostés, la expansión de Hechos, las cartas, el Espíritu, la Gran Comisión (Mateo 28:18-20; Hechos 1:8); la Iglesia como pueblo de Dios de todas las naciones; el «ya pero todavía no»; qué es lo central de este acto (misión en el poder del Espíritu); lo que se verá en el ciclo 9.', 'Hechos 1:8; Mateo 28:19', 'Hechos 1:1-11; Mateo 28:16-20', 'iglesia|misi[oó]n|Gran Comisi[oó]n|Pentecostés|Hechos; grudem, macarthur_ts, ryrie, berkhof'),
51: ('Acto 6, la consumación: la segunda venida, el juicio, la resurrección, los nuevos cielos y la nueva tierra (Apocalipsis 21–22; Isaías 65:17; 2 Pedro 3:13); cómo el final responde al principio (Edén y la Nueva Jerusalén, el árbol de la vida); esperanza cristiana; posturas sobre el milenio solo mencionadas y remitidas al ciclo 13.', 'Apocalipsis 21:3; 2 Pedro 3:13', 'Apocalipsis 21:1-8; 22:1-5', 'consumaci[oó]n|nuevos cielos|Nueva Jerusal[eé]n|segunda venida|Apocalipsis 21; Carballosa, Ladd, MacArthur, Chafer, Ryrie'),
52: ('Cómo se conectan los 66 libros: estructura del Antiguo Testamento (Ley, historia, poesía y sabiduría, profetas mayores y menores) y del Nuevo (Evangelios, Hechos, cartas de Pablo, cartas generales, Apocalipsis); orden canónico y orden cronológico; autores y fechas según las fuentes (con las posturas donde varíen); cómo leer cada bloque con la pregunta «¿cómo anuncia a Cristo y el reino?»; un mapa mental para ubicarse.', 'Lucas 24:44; 2 Timoteo 3:16', 'Lucas 24:44-48', 'libros de la Biblia|Pentateuco|profetas mayores|profetas menores|cartas paulinas; ref4 «Libro por libro», «La Biblia en cápsulas»; Ryrie, Geisler, web_* estructura de la Biblia'),
53: ('Los pactos como hilo de toda la historia: Noé, Abraham, Moisés, David y el nuevo pacto (Jeremías 31:31-34; Lucas 22:20; Hebreos 8); qué es un pacto bíblico; cómo cada pacto retoma y avanza el anterior; las distintas lecturas del pacto (pactos de obras y de gracia, dispensaciones), solo las que traigan las fuentes, como adelanto del ciclo 7.', 'Jeremías 31:33; Lucas 22:20', 'Jeremías 31:31-34; Lucas 22:14-23', 'pacto|alianza|Noé|Abraham|Mois[eé]s|David|nuevo pacto; kline (si está), macarthur_ts, grudem, berkhof, chafer, ryrie, Carballosa'),
54: ('Cómo leer toda la Biblia: planes (de principio a fin, cronológico, por bloques, M’Cheyne), hábitos prácticos (hora, lugar, lectura en voz alta, diario, memorizar), leer en comunidad, oración y lectura, cómo usar este estudio junto a la Biblia; los obstáculos habituales (Levítico, genealogías) y cómo atravesarlos; Salmo 119, Hechos 17:11 y 1 Pedro 2:2; cierra el ciclo 1 y abre el camino hacia los siguientes.', 'Salmo 119:97; 1 Pedro 2:2', 'Salmo 119:97-105; Hechos 17:10-12', 'leer la Biblia|plan de lectura|meditar|memorizar|disciplina; MacArthur (A solas con Dios), Piper, Whitney (si está), ref4 libros de devoción y lectura; web_*'),
}
